CREATE TABLE t.fp_before AS SELECT p.proname::text AS name, md5(pg_get_functiondef(p.oid)) || ':' || coalesce(p.proacl::text, 'default') AS fp FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('admin_doc_fee_change_preview', 'admin_doc_fee_change_apply', 'merge_dealer_settings', 'recalc_tenant_doc_fee');
